function columnProfile(name,rows){
  const raw=rows.map(r=>r[name]),vals=raw.filter(v=>v!==''&&v!=null),labels=vals.map(v=>String(v).trim()),nums=vals.map(Number).filter(Number.isFinite),numeric=vals.length?nums.length/vals.length>=.85:false,unique=[...new Set(labels)],uniqueCount=unique.length,uniqueRatio=vals.length?uniqueCount/vals.length:0;
  const dateHits=labels.filter(v=>!numeric&&/^\d{4}[-/]\d{1,2}[-/]\d{1,2}|^\d{1,2}[-/]\d{1,2}[-/]\d{2,4}/.test(v)&&!Number.isNaN(Date.parse(v))).length,date=dateHits>=Math.max(2,labels.length*.7),integerLike=numeric&&nums.every(v=>Math.abs(v-Math.round(v))<1e-9),binary=uniqueCount===2,missing=raw.length-vals.length;
  const lower=name.toLowerCase(),looksId=/^(id|id_|codigo|código|code|folio|serial|nro|numero|número|registro|equipo_id|cliente_id)/.test(lower)||/_id$/.test(lower)||((/id|codigo|serial/.test(lower))&&uniqueRatio>.75);
  let type=date?'fecha':numeric?(binary?'binaria':'numérica'):(binary?'binaria/categórica':'categórica');return{name,vals,labels,numeric,nums,uniqueCount,uniqueRatio,integerLike,binary,nonEmpty:vals.length,missing,date,looksId,type,unique}
}
function detectIndustrialContext(columns,yName=''){
  const t=(columns.join(' ')+' '+(yName||'')).toLowerCase();
  const areas=[
    ['Confiabilidad y mantenimiento',[[/falla|failure|fault|mtbf|mttr|mantenimiento|downtime|availability|disponibilidad|confiabilidad|rul|vida_util/g,4],[/vibr/g,2],[/temperat|presion/g,.5]]],
    ['Producción',[[/produccion|producción|oee|tiempo_ciclo|ciclo|capacidad|cuello|linea|línea|turno|rendimiento|productividad|throughput/g,3],[/velocidad/g,1]]],
    ['Calidad de procesos',[[/calidad|defecto|rechazo|scrap|merma|inspeccion|grieta|tolerancia/g,4],[/humedad|proceso/g,1]]],
    ['Transporte y logística',[[/ruta|distancia|viaje|flota|camion|camión|entrega|transporte|congestion|sla|retraso/g,3],[/carga/g,1]]],
    ['Ingeniería económica',[[/costo|ingreso|beneficio|precio|flujo|van|tir|payback|rentabilidad|utilidad|inversion|inversión/g,3],[/demanda/g,1]]],
    ['Inventario',[[/inventario|stock|quiebre|lead.?time|reorden|bodega|sku/g,4],[/demanda/g,1]]],
    ['Investigación Operativa',[[/plem|vrp|scheduling|asignacion|asignación|ruteo|programacion|programación|restriccion|restricción|tiempo_servicio|prioridad/g,4],[/capacidad/g,1]]],
    ['RRHH y dotación',[[/ausentismo|dotacion|dotación|turnover|rotacion|rotación|empleado|horas_extra/g,4]]]
  ];
  let best=['Analítica industrial general',0];
  for(const [name,groups] of areas){let score=0;for(const [re,w] of groups){const m=t.match(re);if(m)score+=m.length*w}if(score>best[1])best=[name,score]}
  return best[0]
}
function inferUnit(name){const n=name.toLowerCase();if(/ton[_\/ -]?h|tonelad.*hora|produccion.*ton.*h/.test(n))return'ton/h';if(/kwh|energia.*kw/.test(n))return'kWh';if(/mm[_\/ -]?s|vibracion.*mm/.test(n))return'mm/s';if(/rpm/.test(n))return'RPM';if(/minuto|_min$|tiempo.*min/.test(n))return'min';if(/hora|_h$|hours|hr/.test(n))return'h';if(/temperat/.test(n))return'°C';if(/presion|presión/.test(n))return'bar';if(/porcentaje|pct|tasa|ratio|_pct/.test(n))return'%';if(/kg|peso/.test(n))return'kg';if(/precio|costo|ingreso|flujo|utilidad|van/.test(n))return'$';if(/distancia|km/.test(n))return'km';return''}
function detectPotentialLeakage(rows,columns,y,profiles){if(!y)return[];const leaks=[],yp=profiles.find(p=>p.name===y);columns.forEach(c=>{if(c===y)return;const p=profiles.find(q=>q.name===c),n=c.toLowerCase();if(/post|despues|después|resultado_final|target|label|salida_real|outcome/.test(n))leaks.push({column:c,reason:'El nombre sugiere información disponible después del resultado.'});if(yp?.numeric&&p?.numeric){const pairs=rows.map(r=>[Number(r[c]),Number(r[y])]).filter(v=>v.every(Number.isFinite));if(pairs.length>8){const rr=Math.abs(corr(pairs.map(v=>v[0]),pairs.map(v=>v[1])));if(rr>.995)leaks.push({column:c,reason:`Correlación casi perfecta con Y (|r|=${rr.toFixed(3)}); revisar posible fuga.`})}}});return leaks.slice(0,8)}
function suggestSchema(rows,columns){
  const profs=columns.map(c=>columnProfile(c,rows)),roles={};columns.forEach(c=>roles[c]='X');const scoreRows=[];
  profs.forEach((p,idx)=>{const n=p.name.toLowerCase();let s=0,reasons=[];if(/target|objetivo|salida|resultado|label|class|clase|defecto|falla|fault|failure|flujo_neto|flujo.*net|tiempo_viaje|tiempo_servicio|tiempo_ciclo|rul|quiebre|ausentismo|scrap|oee/.test(n)){s+=14;reasons.push('el nombre parece describir un resultado final')}else if(/calidad|indice|índice|score|demanda|costo|tiempo|riesgo|disponibilidad|flujo|utilidad/.test(n)){s+=7;reasons.push('el nombre puede representar un resultado')}if(p.binary){s+=5;reasons.push('tiene dos valores posibles')}if(!p.numeric&&!p.date&&p.uniqueCount>=3&&p.uniqueCount<=12){s+=4;reasons.push('tiene pocas categorías')}if(p.numeric&&p.uniqueCount>6){s+=2}if(idx===columns.length-1)s+=1;if(p.looksId){s-=100;reasons=['parece un identificador, no un objetivo']}if(p.uniqueRatio>.98&&p.nonEmpty>20&&!p.numeric){s-=8}if(p.date)s-=3;scoreRows.push({name:p.name,score:s,reasons})});
  scoreRows.sort((a,b)=>b.score-a.score);let best=scoreRows[0],y=best?.name||columns[0]||null,confidence=best?.score>=8?'alta':best?.score>=4?'media':'baja';if(y)roles[y]='Y';const excluded=[];profs.forEach(p=>{if(p.name!==y&&p.looksId){roles[p.name]='Excluir';excluded.push(p.name)}});
  const yProf=profs.find(p=>p.name===y)||{numeric:true,binary:false,uniqueCount:0,integerLike:false};let mode='regresión';if(yProf.binary)mode='clasificación binaria';else if(!yProf.numeric&&!yProf.date)mode='multiclase';else if(yProf.integerLike&&yProf.uniqueCount>=3&&yProf.uniqueCount<=15)mode='multiclase';
  const xNames=columns.filter(c=>roles[c]==='X'),xCount=xNames.length,context=detectIndustrialContext(columns,y),hidden=xCount<=3?[4]:xCount<=8?[Math.min(8,xCount+3),4]:[Math.min(16,Math.max(8,xCount+2)),8,4],optimizer=/Confiabilidad|Calidad/.test(context)?'adamw':'adam',loss=mode==='regresión'?'Huber o MSE':mode==='clasificación binaria'?'Binary Cross-Entropy':'Cross-Entropy + Softmax';
  const metrics=mode==='regresión'?['MAE','RMSE','R²']:context.includes('Confiabilidad')?['Recall','F1','Precision']:['F1','Precision','Recall','Accuracy'],leakage=detectPotentialLeakage(rows,columns,y,profs);
  const why=context.includes('Confiabilidad')&&mode!=='regresión'?'En mantenimiento predictivo suele importar detectar fallas reales y revisar falsos negativos.':mode==='regresión'?'MAE traduce el error a unidades reales y RMSE da más peso a errores grandes.':'F1, Precision y Recall permiten separar tipos de error mejor que Accuracy sola.';
  return{roles,y,yProf,mode,context,excluded,xCount,hidden,optimizer,loss,metrics,why,profiles:profs,targetReasons:best?.reasons||[],confidence,leakage,scoreRows}
}
function auditDataset(){
  const rows=State.rows,profiles=State.columns.map(c=>columnProfile(c,rows)),missing=profiles.reduce((s,p)=>s+p.missing,0),seen=new Map(),duplicates=new Set();rows.forEach((r,i)=>{const k=JSON.stringify(State.columns.map(c=>r[c]));if(seen.has(k)){duplicates.add(i);duplicates.add(seen.get(k))}else seen.set(k,i)});const outlierCells=new Set();profiles.filter(p=>p.numeric&&p.nums.length>=8).forEach(p=>{const q1=quantile(p.nums,.25),q3=quantile(p.nums,.75),iqr=q3-q1,lo=q1-1.5*iqr,hi=q3+1.5*iqr;rows.forEach((r,i)=>{const v=Number(r[p.name]);if(Number.isFinite(v)&&(v<lo||v>hi))outlierCells.add(`${i}|${p.name}`)})});const invalid=new Set();profiles.forEach(p=>{if(!p.numeric)return;rows.forEach((r,i)=>{const v=r[p.name];if(v!==''&&v!=null&&!Number.isFinite(Number(v)))invalid.add(`${i}|${p.name}`)})});return{profiles,missing,duplicates,outlierCells,invalid,categorical:profiles.filter(p=>!p.numeric&&!p.date).length,ids:profiles.filter(p=>p.looksId).length}}
