  const t=$('dataTable');if(!t)return;t.innerHTML='';if(!State.columns.length)return;const a=State.audit||auditDataset(),q=(State.tableSearch||'').toLowerCase(),indices=State.rows.map((r,i)=>i).filter(i=>!q||State.columns.some(c=>String(State.rows[i][c]??'').toLowerCase().includes(q)));if(V9.tableSort){indices.sort((ia,ib)=>{const A=State.rows[ia][V9.tableSort],B=State.rows[ib][V9.tableSort],na=Number(A),nb=Number(B),v=Number.isFinite(na)&&Number.isFinite(nb)?na-nb:String(A??'').localeCompare(String(B??''),'es');return v*V9.tableSortDir})}
