function inspectNode(layer,node){const box=$('networkInspector');if(!box)return;const m=currentVisualModel();if(!m){box.hidden=false;box.innerHTML=`<button class="icon-btn inspector-close" onclick="this.parentElement.hidden=true"><svg><use href="#i-close"/></svg></button><h3>${layer===0?'Entrada':'Neurona'} ${layer===0?'X'+(node+1):'H'+layer+'.N'+(node+1)}</h3><p>Entrena la red para inspeccionar activaciones y contribuciones reales.</p>`;return}const s=inspectorSample(m),tr=s.trace;if(layer===0){box.hidden=false;box.innerHTML=`<button class="icon-btn inspector-close" onclick="this.parentElement.hidden=true"><svg><use href="#i-close"/></svg></button><span class="kicker">ENTRADA</span><h3>${esc(m.xs[node]||'X'+(node+1))}</h3><p>Fila ${s.rowNo}</p><div class="summary-grid"><div><span>Valor real</span><b>${fmtN(s.raw[node])}</b></div><div><span>Normalizado</span><b>${fmtN(s.x[node])}</b></div><div><span>Unidad</span><b>${esc(State.columnMeta?.[m.xs[node]]?.unit||'—')}</b></div></div>`;return}const li=layer-1,L=tr.layers[li];if(!L||node>=L.a.length)return;const contrib=L.prev.map((v,i)=>({i,x:v,w:L.weights[node][i],xw:v*L.weights[node][i]})),sum=contrib.reduce((q,z)=>q+z.xw,0),b=L.biases[node]||0,z=L.z[node],a=L.a[node],title=layer===m.sizes.length-1?'Salida ŷ':`H${layer} · N${node+1}`;box.hidden=false;box.innerHTML=`<button class="icon-btn inspector-close" onclick="this.parentElement.hidden=true"><svg><use href="#i-close"/></svg></button><span class="kicker">NEURONA · FILA ${s.rowNo}</span><h3>${title}</h3><p>Activación: <b>${esc(L.type)}</b> · salida = <b>${fmtN(a)}</b></p><table><thead><tr><th>Entrada</th><th>x</th><th>w</th><th>x·w</th></tr></thead><tbody>${contrib.slice(0,16).map(c=>`<tr><td>${c.i+1}</td><td>${fmtN(c.x)}</td><td>${fmtN(c.w)}</td><td>${fmtN(c.xw)}</td></tr>`).join('')}</tbody></table><div class="math-display">Σxw = ${fmtN(sum)}\nb = ${fmtN(b)}\nz = ${fmtN(z)}\na = ${esc(L.type)}(z) = ${fmtN(a)}</div>`}
function inspectConnection(layer,i,j){const box=$('networkInspector'),m=currentVisualModel();if(!box)return;if(!m){box.hidden=false;box.innerHTML='<h3>Conexión</h3><p>Entrena la red para ver el peso real.</p>';return}const s=inspectorSample(m),tr=s.trace,w=m.weights[layer]?.[j]?.[i],input=tr.acts[layer]?.[i],c=input*w,from=layer===0?(m.xs[i]||`X${i+1}`):`H${layer}.N${i+1}`,to=layer===m.sizes.length-2?'ŷ':`H${layer+1}.N${j+1}`;box.hidden=false;box.innerHTML=`<button class="icon-btn inspector-close" onclick="this.parentElement.hidden=true"><svg><use href="#i-close"/></svg></button><span class="kicker">CONEXIÓN · FILA ${s.rowNo}</span><h3>${esc(from)} → ${esc(to)}</h3><div class="summary-grid"><div><span>Peso</span><b>${fmtN(w)}</b></div><div><span>Entrada</span><b>${fmtN(input)}</b></div><div><span>Contribución</span><b>${fmtN(c)}</b></div></div><div class="math-display">x · w = ${fmtN(input)} · ${fmtN(w)} = ${fmtN(c)}</div><p>${c<0?'Esta conexión redujo la suma ponderada de la neurona destino para esta fila.':'Esta conexión aumentó la suma ponderada de la neurona destino para esta fila.'}</p>`}
function updateNetworkWeights(m){if(!m)return;State.liveModel=m;const sizes=[...m.sizes],edges=$('networkSvg')?.querySelectorAll('.edge');if(!edges?.length||+$('architectureTitle')?.textContent.split(' → ')[0]!==sizes[0]){renderNetworkVisual();return}for(let l=0;l<sizes.length-1;l++){const W=m.weights[l],maxW=Math.max(1e-9,...W.flat().map(Math.abs));document.querySelectorAll(`#networkSvg .edge[data-edge-layer="${l}"]`).forEach(e=>{const i=+e.dataset.edgeFrom,j=+e.dataset.edgeTo,w=W?.[j]?.[i];if(!Number.isFinite(w))return;e.classList.toggle('weight-pos',w>=0);e.classList.toggle('weight-neg',w<0);e.style.strokeWidth=(.7+4*Math.abs(w)/maxW).toFixed(2);e.style.opacity=(.3+.65*Math.abs(w)/maxW).toFixed(2)});}mirrorTrainingSvg()}
function liveViz(m,val){updateNetworkWeights(m);const cv=$('predChart');if(!m.classification&&val.length){const q=collectPreds(m,val);cv.style.display='';drawParity(cv,q.y,q.p)}}
function sleepAnim(ms){return new Promise(async resolve=>{while(State.animPaused)await new Promise(r=>setTimeout(r,80));setTimeout(resolve,ms/Math.max(.25,State.animationSpeed||1))})}
function clearPreviewActive(){['networkSvg','trainingSvg'].forEach(id=>{const s=$(id);if(!s)return;s.querySelectorAll('.svg-node').forEach(g=>g.classList.remove('active'));s.querySelectorAll('.edge').forEach(g=>g.classList.remove('active','back'))})}
function applyActive(selector,cls='active'){['networkSvg','trainingSvg'].forEach(id=>$(id)?.querySelectorAll(selector).forEach(e=>e.classList.add(cls)))}
async function animateNetworkPass(){const m=currentVisualModel();if(!m){notify('Entrena la red o inicia un entrenamiento para animar valores reales.','warning');return}State.animBusy=true;const s=inspectorSample(m),tr=s.trace;clearPreviewActive();setNetworkMotion(`<strong>Fila ${s.rowNo}:</strong> comienza el forward con valores normalizados reales.`);for(let l=0;l<m.sizes.length;l++){if(l>0)applyActive(`.edge[data-edge-layer="${l-1}"]`);applyActive(`.svg-node[data-layer="${l}"]`);const val=l===0?tr.acts[0].slice(0,3).map(fmtN).join(', '):tr.acts[l].slice(0,3).map(fmtN).join(', ');$('phaseLabel').textContent='FORWARD';$('phaseTitle').textContent=l===0?'Entradas X':l===m.sizes.length-1?'Predicción ŷ':`Capa H${l}`;$('phaseMath').textContent=l===0?`x = [${val}${tr.acts[0].length>3?', …':''}]`:`a${l} = f(W${l}a${l-1}+b${l}) = [${val}${tr.acts[l].length>3?', …':''}]`;await sleepAnim(260)}const pred=m.classification?tr.y:tr.y*m.stats.ys+m.stats.ym,real=s.yRaw,loss=m.classification?lossValue(s.yNorm,tr.y,'bce'):(real-pred)**2;setNetworkMotion(`<strong>Loss:</strong> y = ${fmtN(real)} · ŷ = ${fmtN(pred)} · pérdida de esta fila ≈ ${fmtN(loss)}.`);$('phaseLabel').textContent='LOSS';$('phaseTitle').textContent='Comparar predicción con valor real';$('phaseMath').textContent=`y = ${fmtN(real)}\nŷ = ${fmtN(pred)}\nL ≈ ${fmtN(loss)}`;await sleepAnim(420);for(let l=m.sizes.length-2;l>=0;l--){applyActive(`.edge[data-edge-layer="${l}"]`,'back');$('phaseLabel').textContent='BACKPROP';$('phaseTitle').textContent=`Gradiente vuelve por ${l===0?'entradas':'H'+l}`;$('phaseMath').textContent='∂L/∂wᵢⱼ = sensibilidad × activación anterior';await sleepAnim(210)}$('phaseLabel').textContent='UPDATE';$('phaseTitle').textContent='El optimizador actualiza los pesos';$('phaseMath').textContent=`w ← w − η · ∂L/∂w\nη = ${+$('learningRate').value||0.03}`;await sleepAnim(320);clearPreviewActive();setNetworkMotion('Recorrido completado. Toca una neurona o cable para inspeccionar los valores de esta fila.');State.animBusy=false}
function animationStep(){const phases=['forward','loss','backprop','update'];State.animStep=(State.animStep||0)%phases.length;const p=phases[State.animStep++];clearPreviewActive();if(p==='forward'){applyActive('.svg-node[data-layer="0"]');$('phaseLabel').textContent='FORWARD';$('phaseTitle').textContent='Las X entran a la red';$('phaseMath').textContent='zⱼ = Σᵢ wᵢⱼxᵢ + bⱼ\naⱼ = f(zⱼ)'}else if(p==='loss'){$('phaseLabel').textContent='LOSS';$('phaseTitle').textContent='Se compara y con ŷ';$('phaseMath').textContent='MSE: (y − ŷ)²\nBCE: −[y log ŷ + (1−y)log(1−ŷ)]'}else if(p==='backprop'){applyActive('.edge','back');$('phaseLabel').textContent='BACKPROP';$('phaseTitle').textContent='Se calculan gradientes';$('phaseMath').textContent='∂L/∂wᵢⱼ'}else{clearPreviewActive();$('phaseLabel').textContent='UPDATE';$('phaseTitle').textContent='El optimizador cambia W y b';$('phaseMath').textContent='W ← W − η·gradiente'}}
async function playAnimation(){if(State.animBusy)return;await animateNetworkPass()}

function targetUnit(){const y=targetY();return y?(State.columnMeta?.[y]?.unit||inferUnit(y)):''}
function renderEvaluationMetrics(model,data){const box=$('evaluationMetrics');if(!box)return;box.innerHTML='';const m=model.classification?classificationMetrics(model,data):regressionMetrics(model,data),unit=targetUnit(),defs=model.classification?[['Accuracy','metricAccuracy','Proporción total clasificada correctamente.'],['Precision','metricPrecision','De los casos predichos como positivos, cuántos eran positivos.'],['Recall','metricRecall','De los positivos reales, cuántos detectó el modelo.'],['F1','metricF1','Equilibrio armónico entre Precision y Recall.']]:[['MAE','metricMAE',`Error absoluto promedio${unit?' en '+unit:''}.`],['RMSE','metricRMSE',`Error cuadrático típico${unit?' en '+unit:''}; penaliza más errores grandes.`],['R²','metricR2','Proporción de variabilidad de Y explicada respecto de usar solo la media.']];defs.forEach(([name,id,desc])=>{if(!$(id)?.checked)return;const key=name==='R²'?'R2':name,val=m[key],display=Number.isFinite(val)?(model.classification||name==='R²'?val.toFixed(3):`${val.toFixed(3)}${unit?' '+unit:''}`):'—',d=document.createElement('article');d.className='metric-card flip-mini';d.innerHTML=`<div class="mini-front"><span>${name}</span><b>${display}</b><p>${desc}</p></div><div class="mini-back"><span>¿QUÉ SIGNIFICA?</span><b>${display}</b><p>${metricInterpretation(name,val,model)}</p></div>`;d.onclick=()=>d.classList.toggle('is-flipped');box.appendChild(d)});if(model.classification&&m.tp!==undefined){const d=document.createElement('article');d.className='dynamic-card cm-wrap';d.innerHTML=`<div class="card-topline"><div><span class="kicker">MATRIZ DE CONFUSIÓN</span><h2>Real vs predicho</h2></div></div><div class="matrix-wrap"><table class="cm"><tr><th></th><th>Pred 0</th><th>Pred 1</th></tr><tr><th>Real 0</th><td class="ok">${m.tn}</td><td class="bad">${m.fp}</td></tr><tr><th>Real 1</th><td class="bad">${m.fn}</td><td class="ok">${m.tp}</td></tr></table></div>`;box.appendChild(d)}}
function metricInterpretation(name,val,model){const y=targetY()||'Y',unit=targetUnit();if(!Number.isFinite(val))return'Sin valor disponible.';if(name==='MAE')return`En promedio, la predicción se separa aproximadamente ${val.toFixed(3)}${unit?' '+unit:''} del valor real de ${y}.`;if(name==='RMSE')return`El error cuadrático es ${val.toFixed(3)}${unit?' '+unit:''}; errores grandes influyen más que en MAE.`;if(name==='R²')return val>=0?`El modelo explica aproximadamente ${(100*val).toFixed(1)}% de la variabilidad observada de ${y} frente al baseline de la media.`:`El modelo rinde peor que predecir la media en este conjunto.`;if(name==='Recall')return`Detecta aproximadamente ${(100*val).toFixed(1)}% de los positivos reales. Revisa el costo de los falsos negativos en tu contexto.`;if(name==='Precision')return`De los positivos que predice, aproximadamente ${(100*val).toFixed(1)}% son positivos reales.`;if(name==='Accuracy')return`Acierta aproximadamente ${(100*val).toFixed(1)}% del total; puede ser engañosa si las clases están desbalanceadas.`;return`F1 = ${val.toFixed(3)} resume el equilibrio entre Precision y Recall.`}
function interpretTrainingForUser(net){const box=$('resultMeaningBox');if(!box||!net?.trained)return;const t=net.trained,m=t.model,lastTr=t.trainHist.at(-1),lastVa=t.valHist.at(-1),evalData=prepareRows(State.split.test.length?State.split.test:State.split.val,m.stats).data,context=State.schema?.context||detectIndustrialContext(State.columns,targetY());let html=`<strong>${esc(context)}</strong><div class="decision-list">`;if(m.classification){const cm=classificationMetrics(m,evalData);html+=`<div class="decision-item"><strong>Recall ${(cm.Recall*100).toFixed(1)}%</strong><p>Indica qué fracción de los positivos reales detectó la red.</p></div><div class="decision-item"><strong>Precision ${(cm.Precision*100).toFixed(1)}%</strong><p>Indica cuántas alertas positivas fueron correctas.</p></div>`}else{const r=regressionMetrics(m,evalData),u=targetUnit();html+=`<div class="decision-item"><strong>MAE ${r.MAE.toFixed(3)}${u?' '+u:''}</strong><p>En promedio absoluto, esa es la distancia entre predicción y realidad.</p></div><div class="decision-item"><strong>RMSE ${r.RMSE.toFixed(3)}${u?' '+u:''}</strong><p>Los errores grandes pesan más en esta métrica.</p></div><div class="decision-item"><strong>R² ${r.R2.toFixed(3)}</strong><p>${metricInterpretation('R²',r.R2,m)}</p></div>`}const diag=interpretLearningCurve(t.trainHist,t.valHist);html+=`<div class="decision-item"><strong>Generalización</strong><p>${esc(diag)}</p></div><div class="decision-item"><strong>Siguiente revisión</strong><p>Compara estas métricas con el rango y costo real de error de ${esc(targetY()||'Y')}. El modelo apoya una decisión; no define por sí solo qué hacer.</p></div></div>`;box.innerHTML=html;updateResultBacks();updateDecisionPanel();markFlowState()}
function updateResultBacks(){const t=currentNet()?.trained;if(!t)return;const tr=t.trainHist,va=t.valHist,best=Math.min(...va),bi=va.indexOf(best)+1,lastTr=tr.at(-1),lastVa=va.at(-1);if($('lossCardBack'))$('lossCardBack').innerHTML=`<p><strong>Train final:</strong> ${fmtN(lastTr)}<br><strong>Validation final:</strong> ${fmtN(lastVa)}<br><strong>Mejor época:</strong> ${bi}<br><strong>Mejor val loss:</strong> ${fmtN(best)}<br><strong>Diferencia final:</strong> ${fmtN(lastVa-lastTr)}</p><p>${esc(interpretLearningCurve(tr,va))}</p>`;if(t.preds&&$('parityCardBack')){const e=t.preds.y.map((y,i)=>y-t.preds.p[i]),bias=mean(e),r=regressionMetrics(t.model,prepareRows(State.split.test.length?State.split.test:State.split.val,t.model.stats).data);$('parityCardBack').innerHTML=`<p><strong>MAE:</strong> ${fmtN(r.MAE)} ${esc(targetUnit())}<br><strong>RMSE:</strong> ${fmtN(r.RMSE)} ${esc(targetUnit())}<br><strong>R²:</strong> ${fmtN(r.R2)}<br><strong>Sesgo medio (real−pred):</strong> ${fmtN(bias)}</p><p>Observa si los puntos siguen la diagonal o si hay zonas donde el modelo falla sistemáticamente.</p>`}}

function analyzeCurrentModel(){const t=currentNet()?.trained;if(!t){notify('Entrena la red actual primero.','warning');return}const m=t.model;if(m.classification){notify('Para clasificación binaria usa ROC/PR y permutation importance se puede estudiar por separado.','info');renderThresholdLab();activateTab('lab75');return}const data=preparedForTrained(m,State.split.test.length?State.split.test:State.split.val);if(!data.length)return;const ys=data.map(o=>o.y*m.stats.ys+m.stats.ym),ps=data.map(o=>forward(m,o.x,false).y*m.stats.ys+m.stats.ym),res=ys.map((y,i)=>y-ps[i]);drawScatter($('residualCanvas'),ps.map((p,i)=>[p,res[i]]),true);drawHistogram($('residualHistCanvas'),res);const base=Math.sqrt(mean(res.map(v=>v*v))),rows=[];m.xs.forEach((name,j)=>{const perm=data.map(o=>({x:o.x.slice(),y:o.y})),vals=shuf(perm.map(o=>o.x[j]),seeded((+$('trainingSeed')?.value||42)+j+1));perm.forEach((o,i)=>o.x[j]=vals[i]);const rmse=Math.sqrt(mean(perm.map(o=>{const y=o.y*m.stats.ys+m.stats.ym,p=forward(m,o.x,false).y*m.stats.ys+m.stats.ym;return(y-p)**2})));rows.push({name,delta:rmse-base,rmse})});rows.sort((a,b)=>b.delta-a.delta);State.importance=rows;$('importanceTable').innerHTML='<table><thead><tr><th>Variable</th><th>Δ RMSE al permutar</th><th>RMSE permutado</th></tr></thead><tbody>'+rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.delta.toFixed(4)}</td><td>${r.rmse.toFixed(4)}</td></tr>`).join('')+'</tbody></table>';if($('analysisSummary'))$('analysisSummary').innerHTML=`<strong>RMSE base:</strong> ${fmtN(base)} ${esc(targetUnit())}. Las primeras variables de la tabla son aquellas cuya información usa más el modelo. Esto no demuestra causalidad.`;updateDecisionPanel();notify('Análisis de residuos e importancia actualizado.','success')}
function updateDecisionPanel(){const s=State.schema||suggestSchema(State.rows,State.columns),ctx=s.context||'Analítica industrial general',imp=State.importance||[],top=imp.slice(0,4);if($('decisionImportance'))$('decisionImportance').innerHTML=top.length?top.map((x,i)=>`<div class="decision-item"><strong>${i+1}. ${esc(x.name)}</strong><p>Al permutarla, RMSE cambió ${fmtN(x.delta)}. Indica dependencia predictiva, no causalidad.</p></div>`).join(''):'<div class="decision-item"><strong>Aún sin ranking predictivo</strong><p>Entrena una regresión y ejecuta “Analizar modelo” para estimar permutation importance.</p></div>';const vars=top.map(x=>x.name),v1=vars[0]||State.columns.find(c=>State.roles[c]==='X')||'la variable principal',v2=vars[1]||'otra variable relevante',questions={
  'Confiabilidad y mantenimiento':[`¿Existe un umbral de ${v1} asociado a mayor probabilidad de falla?`,`¿Qué ocurre cuando ${v1} y ${v2} cambian simultáneamente?`,'¿La antigüedad, equipo o turno está confundiendo la relación?','¿Cómo cambia el costo de falsos negativos al mover el threshold?'],
  'Producción':[`¿En qué rango de ${v1} aumenta el tiempo de ciclo o baja productividad?`,`¿${v2} cambia por turno o línea?`,'¿La predicción podría alimentar scheduling o capacidad?','¿Hay zonas del proceso con errores residuales sistemáticos?'],
  'Transporte y logística':[`¿Cómo cambia el tiempo estimado al variar ${v1}?`,`¿Existe interacción entre ${v1} y ${v2}?`,'¿La predicción puede alimentar un VRP o un SLA?','¿El error es aceptable en rutas críticas?'],
  'Ingeniería económica':[`¿Cuánto cambia el resultado predicho ante variaciones de ${v1}?`,`¿Conviene llevar la predicción a un análisis de sensibilidad o Monte Carlo?`,'¿Qué costo tiene el error de predicción en VAN/TIR?','¿Hay variables que representan información disponible solo después de decidir?']
};const qs=questions[ctx]||[`¿Qué rango de ${v1} cambia más la predicción?`,`¿Cómo interactúan ${v1} y ${v2}?`,'¿Qué decisión operativa usaría esta predicción como parámetro?','¿Qué costo tiene un error del tamaño observado?'];if($('decisionQuestions'))$('decisionQuestions').innerHTML=qs.map(q=>`<div class="decision-item"><p>${esc(q)}</p></div>`).join('');if($('iciConnection'))$('iciConnection').innerHTML=[['Confiabilidad','Falla, MTBF, MTTR, RUL y disponibilidad.'],['Investigación Operativa','Predicciones como parámetros para PLEM, VRP, scheduling e inventario.'],['Ingeniería económica','Costo, demanda, riesgo, flujo y evaluación VAN/TIR posterior.'],['Producción','OEE, productividad, defectos y tiempos de ciclo.'],['Logística','Tiempo de viaje, retrasos, SLA y demanda.'],['Calidad','Defectos, scrap y variables de proceso.'],['Inventario','Demanda, quiebre y lead time.'],['RRHH','Ausentismo, productividad y dotación.']].map(([k,v])=>`<div class="ici-item"><strong>${k}</strong><span>${v}</span></div>`).join('')}

function renderComparison(){const box=$('comparisonTable');if(!box)return;let html='<table><thead><tr><th>Red</th><th>Arquitectura</th><th>Optimizador</th><th>Loss</th><th>Test loss</th><th>Parámetros</th><th>Complejidad</th><th>Generalización</th></tr></thead><tbody>';State.networks.forEach(n=>{const t=n.trained,s=t?.settings||{},sizes=[numericX().length,...n.hidden,1];let p=0;for(let i=0;i<sizes.length-1;i++)p+=sizes[i]*sizes[i+1]+sizes[i+1];const diag=t?interpretLearningCurve(t.trainHist,t.valHist):'Sin entrenar';html+=`<tr><td>${esc(n.name)}</td><td>${sizes.join('→')}</td><td>${esc(s.opt||'—')}</td><td>${esc(s.lossType||'—')}</td><td>${Number.isFinite(t?.testLoss)?t.testLoss.toFixed(6):'—'}</td><td>${p}</td><td>${p<100?'baja':p<1000?'media':'alta'}</td><td>${esc(diag)}</td></tr>`});html+='</tbody></table><p class="note">La tabla no declara una red “ganadora”. Compara error, complejidad, estabilidad y señales de overfitting según el objetivo industrial.</p>';box.innerHTML=html}
function simulateOptimizer(type,w0,g,lr,steps){let w=w0,v=0,s=0,m=0,t=0,u=0,arr=[w];for(let k=0;k<steps;k++){t++;if(type==='sgd')w-=lr*g;else if(type==='momentum'){v=.9*v-lr*g;w+=v}else if(type==='nesterov'){const old=v;v=.9*v-lr*g;w+=-.9*old+1.9*v}else if(type==='adagrad'){s+=g*g;w-=lr*g/(Math.sqrt(s)+1e-8)}else if(type==='rmsprop'){s=.9*s+.1*g*g;w-=lr*g/(Math.sqrt(s)+1e-8)}else if(type==='adam'||type==='adamw'){m=.9*m+.1*g;s=.999*s+.001*g*g;const mh=m/(1-.9**t),vh=s/(1-.999**t);if(type==='adamw')w*=1-lr*.01;w-=lr*mh/(Math.sqrt(vh)+1e-8)}else if(type==='adamax'){m=.9*m+.1*g;u=Math.max(.999*u,Math.abs(g));w-=lr/(1-.9**t)*m/(u+1e-8)}arr.push(w)}return arr}
function renderOptimizerVisibility(){const box=$('optimizerVisibility');if(!box)return;const types=['sgd','momentum','nesterov','adagrad','rmsprop','adam','adamw','adamax'];box.innerHTML=types.map(t=>`<label><input type="checkbox" data-opt-vis="${t}" ${State.optimizerVisibility[t]===false?'':'checked'}>${t.toUpperCase()}</label>`).join('');box.querySelectorAll('[data-opt-vis]').forEach(i=>i.onchange=()=>{State.optimizerVisibility[i.dataset.optVis]=i.checked;if(State.optimizerCompareData)drawOptimizerComparison(State.optimizerCompareData)})}
function runOptimizerComparison(){const w0=+$('compareWeight').value||1,g=+$('compareGradient').value||.3,lr=+$('compareLR').value||.1,steps=Math.max(1,+$('compareSteps').value||30),types=['sgd','momentum','nesterov','adagrad','rmsprop','adam','adamw','adamax'],data={};types.forEach(t=>data[t]=simulateOptimizer(t,w0,g,lr,steps));State.optimizerCompareData=data;renderOptimizerVisibility();drawOptimizerComparison(data);$('optimizerComparisonTable').innerHTML='<table><thead><tr><th>Optimizador</th><th>Peso inicial</th><th>Peso final</th><th>Cambio</th></tr></thead><tbody>'+types.map(t=>{const end=data[t].at(-1);return`<tr><td>${t.toUpperCase()}</td><td>${w0.toFixed(6)}</td><td>${end.toFixed(6)}</td><td>${(end-w0).toFixed(6)}</td></tr>`}).join('')+'</tbody></table>'}

function applyGeneralizationSuggestion(){const t=currentNet()?.trained;if(!t){$('useEarlyStopping').checked=true;$('useDropout').checked=true;$('dropoutRate').value=.2;notify('Aplicada una base conservadora: Early Stopping + Dropout 0.20.','success');return}const msg=interpretLearningCurve(t.trainHist,t.valHist);if(/overfitting/i.test(msg)){$('useEarlyStopping').checked=true;$('useDropout').checked=true;$('dropoutRate').value=.2;$('useL2').checked=true;$('l2Lambda').value=.001}else if(/underfitting/i.test(msg)){$('useDropout').checked=false;$('useL1').checked=false;$('useL2').checked=false;$('epochs').value=Math.min(2000,Math.round((+$('epochs').value||150)*1.4))}notify('Configuración sugerida aplicada. Vuelve a entrenar y compara Validation.','success')}
function markFlowState(){const hasData=State.rows.length>0,hasModel=State.networks.length>0,trained=!!currentNet()?.trained;document.querySelectorAll('[data-step-state="data"]').forEach(i=>i.className=hasData?'done':'');document.querySelectorAll('[data-step-state="model"]').forEach(i=>i.className=hasModel?(hasData?'ready':''):'');document.querySelectorAll('[data-step-state="train"]').forEach(i=>i.className=trained?'done':hasModel?'ready':'');document.querySelectorAll('[data-step-state="results"]').forEach(i=>i.className=trained?'ready':'')}

function contextExample(kind){const r=seeded(20260924),rows=[];for(let i=0;i<260;i++){if(kind==='Confiabilidad'){const vibr=1+r()*8,temp=45+r()*55,h=100+r()*7900,pres=2+r()*7,carga=.3+r()*.7,risk=-6+.52*vibr+.035*(temp-60)+.00025*h+.9*carga,fail=(1/(1+Math.exp(-risk))>r())?1:0;rows.push({equipo_id:`EQ-${1000+i}`,vibracion_mm_s:+vibr.toFixed(2),temperatura_C:+temp.toFixed(1),horas_operacion:+h.toFixed(0),presion_bar:+pres.toFixed(2),carga_motor:+carga.toFixed(2),falla_30_dias:fail})}else if(kind==='Producción'){const vel=40+r()*50,temp=120+r()*70,ciclo=90-vel*.45+Math.abs(temp-155)*.12+r()*7,def=(Math.abs(temp-155)>25||vel>82||r()<.08)?1:0;rows.push({linea_id:`L${1+i%4}`,velocidad:+vel.toFixed(1),temperatura:+temp.toFixed(1),tiempo_ciclo_min:+ciclo.toFixed(2),turno:['A','B','C'][i%3],defecto:def})}else if(kind==='Logística'){const d=5+r()*95,carga=200+r()*1400,cong=r(),par=Math.floor(r()*6),t=12+d*.72+carga*.006+cong*45+par*4+r()*8;rows.push({distancia_km:+d.toFixed(1),carga_kg:+carga.toFixed(0),congestion:+cong.toFixed(2),paradas:par,tiempo_viaje_min:+t.toFixed(1)})}else if(kind==='Ingeco'){const precio=7000+r()*3500,dem=500+r()*1300,costo=3500+r()*1600,inversion=2e6+r()*3e6,flujo=(precio-costo)*dem-inversion*.08+r()*2e5;rows.push({precio:+precio.toFixed(0),demanda:+dem.toFixed(0),costo_unitario:+costo.toFixed(0),inversion:+inversion.toFixed(0),flujo_neto:+flujo.toFixed(0)})}else if(kind==='IO'){const dem=20+r()*80,dist=5+r()*120,prio=1+Math.floor(r()*4),cap=40+r()*80,service=8+.25*dem+.18*dist-0.06*cap+prio*2+r()*5;rows.push({demanda:+dem.toFixed(1),distancia_km:+dist.toFixed(1),prioridad:prio,capacidad:+cap.toFixed(1),tiempo_servicio_min:+service.toFixed(1)})}else if(kind==='Calidad'){const temp=160+r()*45,pres=3+r()*5,vel=20+r()*40,hum=20+r()*50,def=(Math.abs(temp-180)>14||pres<3.8||hum>58||r()<.05)?1:0;rows.push({temperatura:+temp.toFixed(1),presion_bar:+pres.toFixed(2),velocidad:+vel.toFixed(1),humedad:+hum.toFixed(1),defecto:def})}else{const dem=20+r()*80,lead=1+r()*9,stock=30+r()*160,est=['baja','media','alta'][i%3],q=(dem*lead/5>stock||r()<.06)?1:0;rows.push({sku_id:`SKU-${i+1}`,demanda_diaria:+dem.toFixed(1),lead_time_dias:+lead.toFixed(1),stock_actual:+stock.toFixed(0),temporada:est,quiebre:q})}}return rows}
function readCSV(file){if(!file)return;const fr=new FileReader();fr.onload=()=>{const lines=String(fr.result).replace(/^\uFEFF/,'').replace(/\r/g,'').split('\n').filter(x=>x.trim());if(lines.length<2){notify('El CSV necesita encabezado y al menos una fila.','warning');return}const d=[',',';','\t','|'].map(x=>[x,splitLine(lines[0],x).length]).sort((a,b)=>b[1]-a[1])[0][0],heads=splitLine(lines[0],d).map(x=>x.trim()).filter(Boolean);if(new Set(heads).size!==heads.length){notify('Hay encabezados duplicados. Renómbralos antes de importar.','warning');return}const rows=lines.slice(1).map(line=>{const v=splitLine(line,d),o={};heads.forEach((h,i)=>{const s=(v[i]??'').trim(),clean=s.replace(/,/g,'.'),n=Number(clean);o[h]=Number.isFinite(n)&&s!==''&&!/^0\d+/.test(s)?n:s});return o});loadData(rows);$('homeDatasetName').textContent=file.name;$('csvInput').value='';activateTab('home');notify(`CSV analizado: ${rows.length} filas y ${heads.length} columnas.`,'success')};fr.readAsText(file)}
